SELECT
  'taxonomia_video_v2' AS taxonomy_version,
  (SELECT COUNT(*) FROM public.video_taxonomy_topic_paths tp JOIN public.video_taxonomy_versions tv ON tv.id = tp.taxonomy_version_id WHERE tv.taxonomy_version = 'taxonomia_video_v2') AS topic_paths,
  (SELECT COUNT(*) FROM public.video_taxonomy_technical_compatibility tc JOIN public.video_taxonomy_versions tv ON tv.id = tc.taxonomy_version_id WHERE tv.taxonomy_version = 'taxonomia_video_v2') AS compatibility_rules,
  (SELECT COUNT(*) FROM public.video_taxonomy_terms t JOIN public.video_taxonomy_versions tv ON tv.id = t.taxonomy_version_id WHERE tv.taxonomy_version = 'taxonomia_video_v2') AS controlled_terms;
